-- PostgreSQL only
CREATE TEMP TABLE notes (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  body TEXT NOT NULL
);
INSERT INTO notes (body) VALUES ('first note')
RETURNING id, body;

SELECT id, total FROM orders
WHERE total < 50 OR (total = 50 AND id > 3)
ORDER BY total DESC, id ASC LIMIT 2;

SELECT c.id, COUNT(o.id) FILTER (WHERE o.status = 'paid') AS paid_count,
 COALESCE(SUM(o.total) FILTER (WHERE o.status = 'paid'), 0) AS paid_total
FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id ORDER BY c.id;

SELECT customer_id, COUNT(*) AS all_orders, COUNT(*) FILTER (WHERE status = 'paid') AS paid_orders
FROM orders GROUP BY customer_id
HAVING COUNT(*) > 1 AND COUNT(*) FILTER (WHERE status = 'paid') > 0 ORDER BY customer_id;

SELECT id, total, RANK() OVER (ORDER BY total DESC) AS competition,
 DENSE_RANK() OVER (ORDER BY total DESC) AS dense
FROM orders ORDER BY total DESC, id;

SELECT id, total, SUM(total) OVER (ORDER BY total RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS peer_total,
 SUM(total) OVER (ORDER BY total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS row_total
FROM orders ORDER BY total, id;

SELECT customer_id, id, LAST_VALUE(total) OVER (PARTITION BY customer_id ORDER BY id
 ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS final_amount
FROM orders ORDER BY customer_id, id;

WITH RECURSIVE team(id, depth) AS (
 SELECT id, 0 FROM employees WHERE id = 1
 UNION ALL SELECT e.id, t.depth + 1 FROM employees e JOIN team t ON e.manager_id = t.id WHERE t.depth < 3
) SELECT id, depth FROM team ORDER BY depth, id;

WITH RECURSIVE chain(id, manager_id, depth) AS (
 SELECT id, manager_id, 0 FROM employees WHERE id = 4
 UNION ALL SELECT e.id, e.manager_id, c.depth + 1 FROM employees e JOIN chain c ON e.id = c.manager_id WHERE c.depth < 3
) SELECT id, depth FROM chain ORDER BY depth;

